# Independent literal client state machine and receipt encoder.
import random, heapq
from main import run
from test_pipeline import fp

def action(at,s,k,data,end):
 out=at.to_bytes(8,'big')+s.to_bytes(4,'big')+k.encode()
 if k.lower()=='h':
  out+=len(data).to_bytes(8,'big')
  for a,b in data:
   a=a.encode(); b=b.encode();out+=len(a).to_bytes(8,'big')+a+len(b).to_bytes(8,'big')+b
 else:
  data=data.encode();out+=len(data).to_bytes(8,'big')+data
 return out+bytes([bool(end)])

def reference(d):
 states=[dict(state=None,at=0,sent=b'',received=b'',body=b'',frames=0,request_frames=0,payload=0,rframes=0,idx=0,sendend=False,respend=False,finished=False) for c in d['cases']]
 q=[(0,-1,i,0,None) for i in range(len(states))]
 for i,e in enumerate(d['events']):q.append((e['at'],0,i,0,e))
 heapq.heapify(q);seq=0
 def finish(c,state,at):c['state']=state;c['at']=at
 while q:
  at,kind,i,_,ev=heapq.heappop(q)
  if kind==0:
   if ev['kind']=='close':
    for c in states:
     if c['state'] is None:finish(c,'closed',at)
    continue
   s=ev['stream']
   if s%4 or s//4>=len(states):continue
   c=states[s//4]
   if c['state'] is not None or c['respend']:continue
   k=ev['kind'][0];data=ev['fields'] if k=='h' else ev['data']
   c['received']+=action(at,s,k,data,ev['end']);c['rframes']+=1
   if k=='d':c['body']+=data.encode()
   if ev['end']:
    c['respend']=True
    if c['finished']:finish(c,'ok',at)
  elif kind==2:
   c=states[i]
   if c['state'] is None:finish(c,'timeout',at)
  else:
   c=states[i]
   if c['state'] is not None:continue
   frames=d['cases'][i]['frames']
   while c['idx']<len(frames):
    f=frames[c['idx']];c['idx']+=1
    if f['Type']=='sleep':
     seq+=1;heapq.heappush(q,(at+f['Time_to_Stop'],1,i,seq,None));break
    if c['sendend']:finish(c,'send_error',at);break
    k={'headers':'H','data':'D','datagram':'G'}[f['Type']]
    data=f.get('headers_kv',f.get('data_to_transfered'))
    if isinstance(data,dict):data=list(data.items())
    end=f.get('End_Stream',k!='H') and k!='G'
    c['sent']+=action(at,i*4,k,data,end);c['frames']+=1;c['request_frames']+=int(k!='G')
    c['payload']+=sum(len(x.encode())+len(y.encode()) for x,y in data) if k=='H' else len(data.encode())
    c['sendend']=end
   else:
    c['finished']=True
    if c['respend']:finish(c,'ok',at)
    else:seq+=1;heapq.heappush(q,(at+d['timeout_ms'],2,i,seq,None))
 return states

rng=random.Random(93)
for z in range(2000):
 cases=[]
 for i in range(rng.randrange(7)):
  frames=[]
  for j in range(rng.randrange(12)):
   k=rng.choice(['headers','data','datagram','sleep'])
   f={'Type':k}
   if k=='headers':f['data_to_transfered']=[['a','x'],['a','y']]
   elif k=='sleep':f['Time_to_Stop']=rng.randrange(6)
   else:f['data_to_transfered']='hié'
   if k!='sleep' and rng.randrange(2):f['End_Stream']=bool(rng.randrange(2))
   frames.append(f)
  cases.append({'name':str(i),'frames':frames,'expect':{'method':'GET','target':'/','host':'h'}})
 events=[]
 for i in range(rng.randrange(25)):
  e={'at':rng.randrange(20),'kind':rng.choice(['close','headers','data','headers','data'])}
  if e['kind']!='close':
   e['stream']=rng.randrange(30);e['end']=bool(rng.randrange(2))
   if e['kind']=='headers':e['fields']=[[':status','200']]
   else:e['data']='ab😀'
  events.append(e)
 d={'seed':'','definitions':[],'timeout_ms':rng.randrange(1,8),'cases':cases,'events':events,'channels':[]}
 got=run(d)['cases'];expected=reference(d)
 for c,r in zip(got,expected):
  for key,expectedval in [('state',r['state']),('at',r['at']),('frames',r['frames']),('request_frames',r['request_frames']),('payload_bytes',r['payload']),('sent',fp(r['sent'])),('received',fp(r['received'])),('response_body',fp(r['body'])),('response_frames',r['rframes'])]:
   assert c[key]==expectedval,(z,key,c,r,d)
print('2000 differential replay batches passed')
